ACMsg.MICROBIT_RESET = "Resetta la scheda micro:bit in modo programmato, equivalente a premere il pulsante di reset.";
ACMsg.MICROBIT_SLEEP = "Pausa il programma per <b>ms</b> millisecondi.";
ACMsg.MICROBIT_RUNNING_TIME = "Restituisce il tempo trascorso dall'avvio della scheda, in millisecondi.";
ACMsg.MICROBIT_PANIC = "Mostra l'errore <b>error_code</b> sulla matrice LED e riavvia la scheda.";
ACMsg.MICROBIT_TEMPERATURE = "Restituisce la temperatura approssimativa della scheda in gradi Celsius.";
ACMsg.MICROBIT_SET_VOLUME = "Imposta il volume sonoro globale al valore <b>volume</b> compreso tra 0 e 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Scrive il contenuto del buffer <b>buf</b> su una striscia LED WS2812 connessa al <b>pin</b>. Il buffer deve essere di tipo bytes o bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Programma l'esecuzione di una funzione all'intervallo specificato dagli argomenti temporali. Ogni argomento corrisponde a una diversa unità di tempo e i valori si sommano. Quindi <b>run_every(min=1, s=30)</b> pianifica la callback ogni minuto e mezzo. Se all'interno della callback viene sollevata un'eccezione, la funzione viene rimossa dalla schedulazione. Per evitarlo puoi catturare le eccezioni con <b>try/except</b>. <b>run_every</b> può anche essere usato come decoratore, applicato sopra la funzione da schedulare.";
ACMsg.MICROBIT_SCALE = "Converte <b>value</b> dall'intervallo definito da <b>from_low</b> e <b>from_high</b> in un nuovo intervallo definito da <b>to_low</b> e <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Programma l'esecuzione di una funzione all'intervallo specificato dagli argomenti temporali. Ogni argomento corrisponde a una diversa unità di tempo e i valori si sommano. Così, <b>run_every(min=1, s=30)</b> pianifica la callback ogni minuto e mezzo. Se nella callback viene sollevata un'eccezione, la funzione viene sospesa dalla schedulazione. Per evitarlo puoi gestire le eccezioni con <b>try/except</b>. <b>run_every</b> può anche essere usato come funzione, passando la funzione da schedulare come primo argomento.";
ACMsg.MICROBIT_DISPLAY = "Questo modulo controlla il display LED 5x5 sulla parte frontale della scheda. Può essere usato per mostrare immagini, animazioni e anche testi.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Restituisce la luminosità del LED nella colonna <b>x</b> e nella riga <b>y</b> come intero tra <b>0</b> (spento) e <b>9</b> (massima).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Imposta la luminosità del LED nella colonna <b>x</b> e nella riga <b>y</b> a <b>value</b>, che deve essere un intero tra <b>0</b> e <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Imposta la luminosità di tutti i LED a <b>0</b> (spento).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Visualizza <b>image</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Se <b>image</b> è una stringa, float o integer, visualizza lettere/cifre in sequenza. Altrimenti, se <b>image</b> è una sequenza iterabile di immagini, mostra queste immagini in sequenza. Ogni lettera, cifra o immagine viene mostrata con <b>delay</b> millisecondi di intervallo. Se <b>wait</b> è <b>True</b>, la funzione blocca l'esecuzione fino al termine dell'animazione; altrimenti l'animazione avviene in background. Se <b>loop</b> è <b>True</b>, l'animazione si ripeterà all'infinito. Se <b>clear</b> è <b>True</b>, il display verrà svuotato al termine dell'iterabile. Nota che gli argomenti <b>wait</b>, <b>loop</b> e <b>clear</b> devono essere specificati usando il loro nome (keyword).";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Scorre orizzontalmente <b>text</b> sul display. Se <b>text</b> è un intero o float viene prima convertito in stringa usando <b>str()</b>. Il parametro <b>delay</b> controlla la velocità di scorrimento. Se <b>wait</b> è <b>True</b>, la funzione blocca l'esecuzione fino al termine dell'animazione; altrimenti l'animazione avviene in background. Se <b>loop</b> è <b>True</b>, l'animazione si ripeterà all'infinito. Se <b>monospace</b> è <b>True</b>, i caratteri occuperanno tutti <b>5</b> colonne di pixel in larghezza; altrimenti ci sarà esattamente <b>1</b> colonna di pixel vuota tra i caratteri mentre scorrono. Nota che gli argomenti <b>wait</b>, <b>loop</b> e <b>monospace</b> devono essere specificati usando il loro nome.";
ACMsg.MICROBIT_DISPLAY_ON = "Usa <b>on()</b> per accendere il display.";
ACMsg.MICROBIT_DISPLAY_OFF = "Usa <b>off()</b> per spegnere il display (consentendo così di riutilizzare i pin GPIO associati al display per altri scopi).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Restituisce <b>True</b> se il display è acceso, altrimenti <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Usa i LED del display in polarizzazione inversa per rilevare la quantità di luce che cade sul display. Restituisce un intero tra <b>0</b> e <b>255</b> che rappresenta il livello di luce; valori più alti indicano più luce.";
ACMsg.MICROBIT_IMAGE = "La classe <b>Image</b> serve a creare immagini che possono essere visualizzate facilmente sulla matrice LED del dispositivo. Dato un oggetto immagine, è possibile mostrarlo tramite l'API <b>display</b>."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Se <b>string</b> è usata, la stringa deve consistere di cifre da 0 a 9 disposte in righe, che descrivono l'immagine, per esempio: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> creerà un'immagine 5x5 a forma di X. La fine di una riga è indicata dai due punti."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Questo metodo crea un'immagine vuota con <b>width</b> colonne e <b>height</b> righe. Il parametro <b>buffer</b> può essere un array di dimensione <b>width</b> * <b>height</b> contenente interi da 0 a 9. Per esempio: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\no\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre> crea un'immagine 2x2 con luminosità 9."
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Sequenza di immagini integrata (animazione), per esempio <b>Image.ALL_CLOCKS</b> o <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Restituisce l'altezza dell'immagine (numero di righe).";
ACMsg.MICROBIT_IMAGE_WIDTH = "Restituisce la larghezza dell'immagine (numero di colonne).";
ACMsg.MICROBIT_IMAGE_COPY = "Restituisce una copia dell'immagine.";
ACMsg.MICROBIT_IMAGE_INVERT = "Restituisce una nuova immagine con la luminosità dei pixel invertita.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Restituisce la luminosità nella colonna <b>x</b> e riga <b>y</b> come intero da <b>0</b> a <b>9</b>.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Imposta la luminosità nella colonna <b>x</b> e riga <b>y</b> a <b>value</b> (un intero da <b>0</b> a <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Imposta tutti i pixel a <b>value</b> (un intero da <b>0</b> a <b>9</b>).";
ACMsg.MICROBIT_IMAGE_SHIFT_LEFT = "Restituisce una nuova immagine spostata a sinistra di <b>n</b> colonne.";
ACMsg.MICROBIT_IMAGE_SHIFT_RIGHT = "Restituisce una nuova immagine spostata a destra di <b>n</b> colonne.";
ACMsg.MICROBIT_IMAGE_SHIFT_UP = "Restituisce una nuova immagine spostata verso l'alto di <b>n</b> righe.";
